def kit_items_with_essential_flag(apps, schema_editor):
    """Kit checklists were lists of names: each item becomes {"item", "essential": False}."""
    AssetModel = apps.get_model("catalogs", "AssetModel")
    for model in AssetModel.objects.all():
        items = [
            item if isinstance(item, dict) else {"item": str(item), "essential": False}
            for item in model.kit_checklist or []
        ]
        if items != model.kit_checklist:
            model.kit_checklist = items
            model.save(update_fields=["kit_checklist"])


